import base64,hashlib,subprocess
from pathlib import Path
root=Path('/home/cat/projects/RK3576/rk3576_multimodal_stage5_review')
assert root.is_dir() and not root.is_symlink()
data=base64.b64decode('')
assert hashlib.sha256(data).hexdigest()=='3642198d82b6a17013c299ec7d938c378aa316786f0bbd4cadb1fdab9193cf02'
target=root/'tools/stage5_board_phase3_run.py'
with target.open('xb') as f: f.write(data)
for sig in ('SIGINT','SIGTERM'):
    cmd=['python3','-I',str(target),'--name','baseline_'+sig.lower(),'--signal',sig,'--trigger','ready','--delay','2','--seconds','120','--timeout','180','--grace','25']
    print('RUN_BASELINE',sig,flush=True)
    r=subprocess.run(cmd,timeout=225)
    if r.returncode: raise SystemExit(r.returncode)
